test('pop returns item with lowest priority', () => {
  const pq = new PriorityQueue();
  pq.push('a', 5);
  pq.push('b', 1);
  pq.push('c', 3);
  expect(pq.pop()).toBe('b');
});

test('pop returns items in priority order', () => {
  const pq = new PriorityQueue();
  [3,1,4,1,5,9,2].forEach((p, i) => pq.push(`item${i}`, p));
  const priorities = [];
  while (pq.size > 0) {
    const item = pq.pop();
    priorities.push(Number(item.replace('item','')));
  }
  const sorted = [...priorities].sort((a,b) => [3,1,4,1,5,9,2][a] - [3,1,4,1,5,9,2][b]);
  expect(priorities).toEqual(sorted);
});

test('peek does not remove item', () => {
  const pq = new PriorityQueue();
  pq.push('only', 1);
  pq.peek();
  expect(pq.size).toBe(1);
});

test('size reflects current count', () => {
  const pq = new PriorityQueue();
  expect(pq.size).toBe(0);
  pq.push('a', 1);
  pq.push('b', 2);
  expect(pq.size).toBe(2);
  pq.pop();
  expect(pq.size).toBe(1);
});

